@app.before_request
def set_session_cookie_secure():
    x_forwarded_proto = flask.request.headers.get("X-Forwarded-Proto", "")
    is_secure = x_forwarded_proto.split(',')[0].strip() == "https"
    flask.current_app.config['SESSION_COOKIE_SECURE'] = is_secure

